#!/usr/bin/env bash
# Weekly MazingiraKenya Narrative-Disinfo queue — 2026-11-16
# Queues UNPUBLISHED drafts (published=false) into Supabase disinfo_items for admin review.
# This run wrote the 4 drafts via a connected Chrome (POST /rest/v1/disinfo_items, 201) because
# the Mac device-bridge shell cannot reach supabase.co (curl HTTP 000 on CONNECT this run).
# This script reproduces the same inserts anywhere Supabase IS reachable, via insert-disinfo-draft.mjs.
#   Usage: bash scripts/queue-disinfo-2026-11-16.sh
set -euo pipefail
cd "$(dirname "$0")/.."

run() { node scripts/insert-disinfo-draft.mjs "$1"; }

run "$(cat <<'JSON'
{"name":"Circulating on social media / climate-skeptic sites","posted_at":"2026-11-16","body":"A 485-million-year temperature record published in the journal Science (and covered by major media) shows Earth is currently in one of its coldest periods in half a billion years — proof that today's warming is trivial, natural and nothing to worry about.","verdict":"Climate denial / manipulated study","verdict_class":"vf","source_url":"https://www.theclimatebrink.com/p/climate-skeptics-have-new-favorite","source_label":"The Climate Brink (Hausfather/Dessler) & Judd et al. 2024, Science; cf. Skeptical Science","rebuttal":"The graph is real, but it is being read backwards. Judd et al.'s 2024 Science reconstruction plots temperature alongside CO2 across 485 million years, and the two rise and fall together — the authors conclude CO2 is 'the dominant driver of Phanerozoic climate,' which supports the CO2-warming link rather than refuting it. Two things the talking point hides: (1) Rate, not just absolute temperature, is what matters — past warm periods built up over millions of years, giving life time to adapt, whereas humans have raised CO2 by roughly 50% in about 150 years and pushed 2024 to ~1.55C above pre-industrial. (2) Rapid past warming was catastrophic, not benign — it is linked to mass extinctions that wiped out roughly 60% of marine species (Late Ordovician) and about 90% of all species (end-Permian). Humans and our farming, cities and coastlines evolved for today's cooler climate. 'We're in an ice age, so warming is fine' cherry-picks half of a study whose own authors say the opposite; for East Africa the fast change shows up as vanishing Mt Kenya/Kilimanjaro ice, heatwaves and drought-to-flood swings."}
JSON
)"

run "$(cat <<'JSON'
{"name":"Circulating on TikTok and Facebook (Kenya floods)","posted_at":"2026-11-16","body":"BREAKING: Kenya's Ministry of Education has postponed the reopening of schools nationwide because of the heavy rains and flooding.","verdict":"Fabricated announcement / impersonation","verdict_class":"vf","source_url":"https://africacheck.org/fact-checks/meta-programme-fact-checks/no-kenya-has-not-postponed-reopening-schools-due-floods","source_label":"Africa Check · fake 'Citizen Digital' graphic + recycled Ruto clip","rebuttal":"No such postponement was announced. Africa Check found the claim spread on TikTok and Facebook (600,000+ views) using two fakes: a 'breaking news' graphic mocked up to look like Citizen Digital announcing nationwide closures — a graphic that appears nowhere on Citizen TV's real website or verified accounts — and a genuine video of President Ruto that actually dates from a May 2024 flooding address, recycled to look current. Schools reopened on schedule, with only localised disruptions in flood-hit areas. Many posts were paired with unrelated 'money-hack' captions, a classic sign of engagement-bait. This is the recurring disaster-disinformation pattern during Kenya's rainy seasons: as Kenya Met warns of heavy, El Nino-enhanced rains across dozens of counties through December 2026, fabricated government 'announcements' and recycled clips spread fast — verify school, evacuation and closure notices against official Ministry of Education and Kenya Met channels before sharing."}
JSON
)"

run "$(cat <<'JSON'
{"name":"Circulating on social media (youth climate commentary, East Africa)","posted_at":"2026-11-16","body":"Climate change is already irreversible and humanity is heading for extinction, so there is no point cutting emissions or taking climate action — we should just accept our fate.","verdict":"Climate doomism / demobilisation","verdict_class":"vc","source_url":"https://observer.ug/news/ugandas-climate-change-knowledge-and-accountability-gap-is-fuelling-disinformation/","source_label":"The Observer (Uganda) on climate 'doomism'; UN/IPCC","rebuttal":"This 'doomism' is the mirror image of denial — and just as demobilising. The Observer notes the 'it's irreversible, accept extinction' framing is spreading among young social-media users in East Africa, and it is harmful because it tells people action is pointless when the science says the opposite. The IPCC is explicit that every fraction of a degree of warming avoided reduces harm, and UN scientists stress that rapid, deep and immediate CO2 cuts can still prevent the worst outcomes; because warming largely halts once emissions reach net zero, near-term cuts directly change the trajectory. A great deal is already locked in and adaptation is essential — but 'locked in' is not 'hopeless.' For East Africa the practical stakes (how much drought, flooding, crop loss and glacier melt the region faces) depend on choices made this decade. Fatalism and denial lead to the same destination: inaction. Neither is supported by the evidence."}
JSON
)"

run "$(cat <<'JSON'
{"name":"Circulating in energy-policy and oil-and-gas promotion (COP30 period)","posted_at":"2026-11-16","body":"Natural gas is a clean 'transition fuel' and the sensible bridge for Africa's energy needs — so expanding East Africa's gas-power plants and LNG projects is good for the climate and for energy access.","verdict":"Greenwashing / misleading framing","verdict_class":"vm","source_url":"https://www.nrdc.org/bio/shruti-shukla/transition-fuel-illusion-how-2025-exposed-limits-global-natural-gas-expansion","source_label":"NRDC 'Transition Fuel Illusion'; re-course 'bridge fuel myth'; Cambridge CISL","rebuttal":"'Clean bridge fuel' is a branding exercise, not a climate fact. Natural gas is mostly methane, a greenhouse gas far more potent than CO2 over the near term, and leaks across production, processing and transport can erase much of gas's supposed advantage over coal — the COP30 methane status report found action still falls far short of the pledged 30% cut by 2030. The economics have also flipped: IRENA found 91% of new renewable projects worldwide were already cheaper than any new fossil option in 2024, solar-plus-storage now rivals or beats new gas on cost, and the IEA reports clean energy draws about two-thirds of global energy investment. For Africa the 'bridge' risks becoming a stranded-asset trap — long-lived, import-exposed, price-volatile infrastructure (East African LNG and gas-power build-outs) locking in emissions and debt, when distributed solar and storage can expand access faster and cheaper, precisely where grids never reached. Gas may have niche roles, but selling fossil-gas expansion as a climate solution is greenwashing, and 'gas or no power' is a false choice."}
JSON
)"

echo "Queued 4 disinfo drafts (2026-11-16) — awaiting admin review."
